insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_dance1_v1'
from (values
('117.306.c.1.A',2,'A dancer notices how much room she has around her and stays aware of her own body''s position in it. This is called what?','["Spatial and kinesthetic awareness", "Stage lighting", "Ticket sales", "Costume design"]'::jsonb,0,'Kinesthetic awareness is sensing the body in space.','original'),
('117.306.c.1.A',2,'When a group of dancers moves across the floor without bumping into each other, they are using what?','["Slow breathing only", "Spatial awareness in a group", "Random movement", "Silent staring"]'::jsonb,1,'Group spatial awareness prevents collisions.','original'),
('117.306.c.1.B',2,'Which habit helps keep a dancer safe during class?','["Ignoring pain", "Skipping the warm-up", "Wearing proper shoes and warming up before dancing", "Dancing with wet floors"]'::jsonb,2,'Safe practice prevents injuries.','original'),
('117.306.c.1.B',2,'Why should a dancer drink water during rehearsal?','["To avoid warming up", "To make the floor slippery", "To slow the music", "To stay hydrated and keep the body working well"]'::jsonb,3,'Hydration supports performance.','original'),
('117.306.c.1.C',2,'Ballet, jazz, tap and modern are examples of what?','["Dance genres", "Music keys", "Costume colors", "Stage lights"]'::jsonb,0,'Each is a genre of dance.','original'),
('117.306.c.1.C',2,'Which term from ballet vocabulary refers to a bend of the knees?','["Leap", "Plie", "Pirouette", "Chasse"]'::jsonb,1,'Plie means to bend.','original'),
('117.306.c.1.D',2,'A dancer shows a tree swaying in the wind using only her body. This is an example of what?','["Memorizing a script", "Reading music", "Identifying an image from the environment through movement", "Designing a poster"]'::jsonb,2,'Movement can represent images from nature.','original'),
('117.306.c.1.D',2,'Which image from the environment could be shown through slow, floating movement?','["A door slamming", "A hammer hitting", "A truck driving fast", "A feather drifting down"]'::jsonb,3,'Slow floating movement matches a drifting feather.','original'),
('117.306.c.2.A',3,'In dance, good alignment means the dancer stacks which parts in a line?','["Head, shoulders, ribs, hips, knees and ankles", "Only the hands", "Only the feet", "Only the chin"]'::jsonb,0,'Alignment stacks the body parts.','original'),
('117.306.c.2.A',3,'Why is proper body alignment important for dancers?','["It hides mistakes", "It helps prevent injury and supports balanced movement", "It removes the need for practice", "It makes the music louder"]'::jsonb,1,'Alignment supports safe, balanced movement.','original'),
('117.306.c.2.B',3,'A student explores movement ideas without a set plan and finds a new way to turn. This is called what?','["Memorization", "Stage direction", "Improvisation", "Notation"]'::jsonb,2,'Improvising is creating movement spontaneously.','original'),
('117.306.c.2.B',3,'What is the purpose of improvising in the creative process?','["To avoid practicing", "To copy another dancer", "To memorize a routine only", "To discover original movement ideas"]'::jsonb,3,'Improvisation supports creativity.','original'),
('117.306.c.2.C',3,'A dancer uses slow, heavy steps and a lowered head to show sadness. She is doing what?','["Expressing emotion through movement", "Counting beats", "Warming up", "Adjusting lights"]'::jsonb,0,'Movement qualities express feelings.','original'),
('117.306.c.2.C',3,'Which movement quality might best express excitement?','["Collapsing downward", "Quick, light and bouncing steps", "Slow sinking", "Slow, still pauses"]'::jsonb,1,'Fast, bouncy movement shows excitement.','original'),
('117.306.c.2.D',3,'A choreographer makes a short dance in A-B-A form where the first section returns at the end. This is an example of what?','["A warm-up", "A costume change", "A basic compositional form", "A rehearsal schedule"]'::jsonb,2,'ABA is a basic compositional form.','original'),
('117.306.c.2.D',3,'Which element of dance includes time, space and energy?','["The ticket price", "The program notes", "The costume list", "The fundamental dance elements used in choreography"]'::jsonb,3,'Time, space and energy are elements of dance.','original'),
('117.306.c.3.A',3,'A student performs a memorized sequence in time with the beat of the music. She shows which skill?','["Rhythmic accuracy", "Costume design", "Set painting", "Stage lighting"]'::jsonb,0,'Rhythmic accuracy means matching the beat.','original'),
('117.306.c.3.A',3,'Why is it important to memorize a sequence before a performance?','["It replaces warm-ups", "It allows the dancer to focus on quality and expression", "It lets her skip rehearsals", "It removes the audience"]'::jsonb,1,'Memorization frees focus for expression.','original'),
('117.306.c.3.B',3,'During practice, a dancer performs one phrase with a strong, sharp force and the next with a soft, flowing force. She is showing the effective use of which dance element?','["Program", "Costume", "Energy", "Stage space"]'::jsonb,2,'Energy is one of the dance elements.','original'),
('117.306.c.3.B',3,'Which choice shows effective use of the element of space?','["Covering the mirror", "Standing still", "Hiding behind a curtain", "Moving at high, middle and low levels"]'::jsonb,3,'Levels are a use of space.','original'),
('117.306.c.3.C',3,'A group performs a dance using canon, where dancers begin the same movement one after another. This is an example of what?','["A choreographic process", "A costume change", "A lighting cue", "A program note"]'::jsonb,0,'Canon is a choreographic device.','original'),
('117.306.c.3.C',3,'In the compositional form theme and variation, what happens?','["Only one move is used", "A movement idea is presented and then changed in different ways", "The dance stops", "The music changes key"]'::jsonb,1,'Variations alter the theme.','original'),
('117.306.c.3.D',3,'A warm-up helps prepare a dancer by doing what?','["Skipping stretching", "Lowering water intake", "Gradually increasing heart rate and loosening muscles", "Making muscles stiffer"]'::jsonb,2,'Warm-ups raise body temperature and prepare muscles.','original'),
('117.306.c.3.D',3,'A cool-down at the end of class helps a dancer do what?','["Avoid recovery", "Raise the pulse", "Start a new routine", "Slowly lower the heart rate and stretch tired muscles"]'::jsonb,3,'Cool-downs help the body recover.','original'),
('117.306.c.4.A',3,'A class learns a folk dance from another country and performs its steps. They are performing dance characteristics from what?','["A diverse culture", "Only the present day", "No culture", "Only modern trends"]'::jsonb,0,'Folk dances reflect a culture.','original'),
('117.306.c.4.A',3,'Why do dance students study dances from several cultures?','["To copy one style only", "To understand how traditions and values are expressed in movement", "To avoid learning steps", "To ignore history"]'::jsonb,1,'Dance reflects culture.','original'),
('117.306.c.4.B',3,'A student performs a minuet and then a swing dance, noticing the changes in clothing, music and manners between eras. She is doing what?','["Choosing steps randomly", "Ignoring history", "Performing dances from different time periods with historical understanding", "Only learning music"]'::jsonb,2,'Context deepens performance.','original'),
('117.306.c.4.B',3,'Which question helps a dancer understand the historical context of a dance?','["How big is the studio?", "What is the tallest dancer?", "What is the price?", "When and why was this dance created, and by whom?"]'::jsonb,3,'Context includes time, place and purpose.','original'),
('117.306.c.4.C',3,'Martha Graham is significant in dance history because she did what?','["Developed a modern dance technique based on contraction and release", "Wrote the first musical", "Invented the tap shoe", "Founded a ballet in Russia"]'::jsonb,0,'Graham created a groundbreaking technique.','original'),
('117.306.c.4.C',3,'Alvin Ailey is known for establishing what?','["A circus act", "A company that celebrates African American cultural heritage through dance", "A film studio", "The first ballroom contest"]'::jsonb,1,'Ailey founded a company with a cultural mission.','original'),
('117.306.c.4.D',3,'Seeing a dance sequence in a music video is an example of dance in which area?','["No area", "Only theater", "Media", "Only classroom"]'::jsonb,2,'Dance appears in media.','original'),
('117.306.c.4.D',3,'A film about a dancer uses choreography to tell the story. This shows dance in what?','["Only books", "Only sports", "Only museums", "Various media and content areas"]'::jsonb,3,'Dance connects to film and other areas.','original'),
('117.306.c.5.A',3,'A student describes a phrase as smooth, sustained and flowing. She is using what?','["Appropriate movement vocabulary", "Silent counting", "Costume terms", "A random list"]'::jsonb,0,'Using terms like smooth and sustained describes movement.','original'),
('117.306.c.5.A',3,'Which term describes a movement quality?','["Proscenium", "Sharp", "Marley", "Costume"]'::jsonb,1,'Sharp describes quality of movement.','original'),
('117.306.c.5.B',2,'Which behavior shows good audience etiquette?','["Walking in front of the stage", "Using a phone with the light on", "Watching quietly and applauding at the end", "Talking loudly"]'::jsonb,2,'Quiet respect is good etiquette.','original'),
('117.306.c.5.B',2,'In the classroom, how should students behave while watching peers perform?','["By laughing at mistakes", "By talking", "By leaving the room", "With respect and attention"]'::jsonb,3,'Respect supports a positive environment.','original'),
('117.306.c.5.C',3,'A teacher links the patterns in a dance to patterns in math. This shows a relationship between dance and what?','["Another content area", "Nothing", "A single color", "A pet"]'::jsonb,0,'Dance connects with math, science and more.','original'),
('117.306.c.5.C',3,'Which connection shows how dance relates to science?','["Counting tickets", "Studying how muscles and bones move during a leap", "Choosing seats", "Reading a menu"]'::jsonb,1,'Anatomy links dance to science.','original'),
('117.306.c.5.D',3,'A dancer records her rehearsal on video to see her posture. She is using technology to do what?','["Skip practice", "Delete the dance", "Analyze and improve her performance", "Avoid feedback"]'::jsonb,2,'Video review helps improvement.','original'),
('117.306.c.5.D',3,'Which technology could help a choreographer plan a dance''s music?','["A calculator only", "A thermometer", "A paper clip", "Music editing software"]'::jsonb,3,'Editing software prepares music.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
